"""Compare readout selectivity on reserved, unedited inputs, not adapter behavior."""
from geometry import *
from roles import *

DEP=(13,15,14,35)
def summary(x):
    if not len(x): return ' - '
    return str(np.quantile(x,[0,.1,.5,.9,1]).round(2))

def guess_masks(d):
    nums=np.vectorize(lambda t: t.strip().isdigit())(d.tok)
    g=d.role==1
    return g&~nums,g&nums

def ord_masks(d):
    c=d.role!=1
    bot=c&(d.rel>=0)
    user=c&(d.rel<=-10)&(d.abs>=3)
    others=c&~bot&~user
    return user,bot,others

def rel_data(site,l,ds):
    X=[]; F=[]
    for d in ds:
        x=d.acts[site]
        s=np.linalg.norm(d.acts[f'resid.{l}'],axis=-1,keepdims=True)
        X.append(x); F.append(x / s)
    S=np.median(np.linalg.norm(ds[0].acts[f'resid.{l}'][ds[0].role==1],axis=-1)); F=[f*S for f in F]
    return F, X, S

def covmat(sets,coefs=None):
    if coefs is None: coefs=np.ones(len(sets))/len(sets)
    return sum((c/len(X))*(X.T@X) for c,X in zip(coefs,sets) if len(X))

def basis_readout(l,site,D,A,reg=0.004,rep=.22,robust=.16,geom=True):
    # Moment-based role projector. Not trained on answers or output preferences.
    S0,X,scale=rel_data(site,l,D+A)
    F=S0 if geom else X
    f0,f1,*frest=F[:len(D)]
    samples=[]; mu=[]; var=[]
    masks0=guess_masks(D[0]); masks1=guess_masks(D[1]);
    for P,p in zip((f0,f0,f1,f1),masks0+masks1):
        if p.sum()==0: continue
        z=P[p]; m=z.mean(0); mu.append(m); var.append(z-m)
    for d,f in zip(D,F):
        mask=d.role!=1
        # Tail text and reply are included among the backgrounds.
        samples.append(f[mask]);
    C=covmat(samples,([.32,.23,.18,.27] if len(samples)==4 else None))
    a0=C.copy()
    rset=[f[d.rel>=0] for f,d in zip(F,D)]
    C=(1-rep)*C+rep*covmat(rset,[.12,.18,.34,.36] if len(rset)==4 else None)
    C+=robust*covmat(var)
    rho=reg*np.trace(a0)
    C.flat[::len(C)+1]+=rho
    M=np.stack(mu,1)
    S=la.solve(C,M,assume_a='pos'); V=M.T@S
    coeff=la.solve(V,np.ones(len(V),dtype=np.float32),assume_a='pos')
    a=S@coeff
    return a,scale,F[-len(A):] if A else [],(F,X)


def inspect_readout():
    D=[Trace(i) for i in DEP]; A=[Trace(i) for i in (30,31,29)];
    sites=[t for t in D[0].acts.files if t.endswith('down_proj') or t.endswith('.linear_attn.out_proj')]
    print('held-out guesses by example:')
    print(*[(i,A[0].tok[i,A[0].role[i]==1].tolist()) for i in range(A[0].shape[0])]);
    for site in sites:
        l=int(site.split('.')[2])+1
        for geom in [True]:
            for reg in [.0007,.0035,.009]:
                a,s,F,_=basis_readout(l,site,D,A,reg=reg,geom=geom)
                print(l,'MLP' if 'mlp' in site else 'LINEAR',reg,geom, 'coefficient norm',np.linalg.norm(a).round(2), 'Rnorm',float(s))
                for t,f in zip(A,F):
                    b=f@a
                    g1,g2=guess_masks(t)
                    k=[np.quantile(abs(b[z]),[.5,.95,.99,1]).round(2) for z in ord_masks(t)]
                    print(t.n, summary(b[g1]),summary(b[g2]), 'nontarget',k[0], 'reply',k[1], 'template',k[2]);
                    if t.n==30 and reg==.0035:
                        print('   exact/variants median',np.round([np.median(b[:10][t.role[:10]==1]),np.median(b[10:][t.role[10:]==1])],2),'worst',[(i,t.tok[i,j],b[i,j].round(2)) for i,j in zip(*np.where((b<.4)&(t.role==1)))])


def attn_blocks():
    a=Trace(13); C=Trace(14);
    for l in [7,11,15,19,23]:
        for h in [a,C]:
            R=h.acts[f'resid.{l}']; P,O,S,Z=attn(R,h.abs,l)
            n,k=h.shape
            masks=[]
            if h.n==13:
                qu_idx=h.pre-4; G=h.role==1; I=(np.arange(k)[None,:]>qu_idx[:,None])&(h.rel<-18)&~G
                masks=[('question',(np.arange(k)[None,:]<=qu_idx[:,None])&(h.abs>=3)),('guess', G),('guess clause rest',I)]
            else:
                masks=[('question',(h.rel<-18)&(h.abs>=3))]
            masks+=[('format',(h.rel>=-18)&(h.rel<=-10)),('template',(h.rel>=-9)&(h.rel<0)),('answer',h.rel>=0)]
            print(l,h.n,'avg attn @ q=is aggregated over heads and contents:', [(k,round(float((P[np.arange(n),[h.qidx(i) for i in range(n)]]*g[:,None,:]).sum(-1).mean()),3)) for k,g in masks])

if __name__=='__main__':
    inspect_readout(); attn_blocks()
PY
